const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { summary: "No rows found in the file." } }];

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const keys = Object.keys(rows[0]);
const find = (...parts) => keys.find(k => parts.some(p => norm(k).includes(p)));

const kPnl = find('realizedpl', 'realizedpnl', 'realized');
const kOpen = find('openingfee');
const kClose = find('closingfee');
const kFund = find('fundingfee');
const kTime = find('tradetime', 'time', 'date');

if (!kPnl) {
  return [{ json: { summary: "No Realized P&L column found. Columns: " + keys.join(', ') } }];
}

const num = v => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.+-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};

let trades = rows.map(r => ({
  pnl: num(r[kPnl]),
  fees: num(kOpen && r[kOpen]) + num(kClose && r[kClose]) + num(kFund && r[kFund]),
  time: kTime ? new Date(String(r[kTime]).replace(' ', 'T')) : null,
}));

const hasTimes = kTime && trades.every(t => !isNaN(t.time));
if (hasTimes) trades.sort((a, b) => a.time - b.time);

const n = trades.length;
const wins = trades.filter(t => t.pnl > 0);
const losses = trades.filter(t => t.pnl < 0);
const sum = a => a.reduce((s, t) => s + t.pnl, 0);
const totalNet = sum(trades);
const totalFees = trades.reduce((s, t) => s + t.fees, 0);
const grossWin = sum(wins);
const grossLoss = Math.abs(sum(losses));
const avgWin = wins.length ? grossWin / wins.length : 0;
const avgLoss = losses.length ? grossLoss / losses.length : 0;
const best = Math.max(...trades.map(t => t.pnl));
const worst = Math.min(...trades.map(t => t.pnl));

let cum = 0, peak = 0, maxDD = 0, streak = 0, maxStreak = 0;
for (const t of trades) {
  cum += t.pnl;
  peak = Math.max(peak, cum);
  maxDD = Math.max(maxDD, peak - cum);
  if (t.pnl < 0) { streak++; maxStreak = Math.max(maxStreak, streak); } else { streak = 0; }
}

const f = x => x.toFixed(2);
const range = hasTimes
  ? trades[0].time.toISOString().slice(0, 10) + ' to ' + trades[n - 1].time.toISOString().slice(0, 10)
  : '';

const lines = [
  'Trade journal summary' + (range ? ' (' + range + ')' : ''),
  'Trades: ' + n + ' (wins ' + wins.length + ', losses ' + losses.length + ')',
  'Win rate: ' + f((wins.length / n) * 100) + '%',
  'Net P&L: ' + f(totalNet) + ' USDT',
  'Fees and funding: ' + f(totalFees) + ' USDT',
  'Avg win: ' + f(avgWin) + ' | Avg loss: ' + f(avgLoss),
  'Profit factor: ' + (grossLoss ? f(grossWin / grossLoss) : 'n/a (no losing trades)'),
  'Avg per trade: ' + f(totalNet / n) + ' USDT',
  'Best: ' + f(best) + ' | Worst: ' + f(worst),
  'Max drawdown: ' + f(maxDD) + ' USDT',
  'Longest losing streak: ' + maxStreak,
];
if (totalNet > 0 && best > 0) lines.push('Best trade = ' + f((best / totalNet) * 100) + '% of net profit');
if (n < 30) lines.push('Note: under 30 trades, too few to judge a strategy.');

return [{ json: { summary: lines.join('\n') } }];
